package com.epam.edp.demo.repository;

import com.epam.edp.demo.entity.BookingStatus;
import com.epam.edp.demo.entity.ReportData;
import com.epam.edp.demo.entity.TourDailyReportData;
import com.epam.edp.demo.entity.TourWeeklyReportData;
import com.epam.edp.demo.entity.TravelAgentDailyReportData;
import com.epam.edp.demo.entity.TravelAgentWeeklyReportData;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import software.amazon.awssdk.core.pagination.sync.SdkIterable;
import software.amazon.awssdk.enhanced.dynamodb.DynamoDbEnhancedClient;
import software.amazon.awssdk.enhanced.dynamodb.DynamoDbIndex;
import software.amazon.awssdk.enhanced.dynamodb.DynamoDbTable;
import software.amazon.awssdk.enhanced.dynamodb.TableSchema;
import software.amazon.awssdk.enhanced.dynamodb.model.BatchWriteItemEnhancedRequest;
import software.amazon.awssdk.enhanced.dynamodb.model.Page;
import software.amazon.awssdk.enhanced.dynamodb.model.PageIterable;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.ConditionalCheckFailedException;
import software.amazon.awssdk.services.dynamodb.model.UpdateItemRequest;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class ReportRepositoryImplTest {

    @Mock
    private DynamoDbClient dynamoDbClient;

    @Mock
    private DynamoDbEnhancedClient dynamoDbEnhancedClient;

    @Mock
    private DynamoDbTable<ReportData> reportsTable;

    @Mock
    private DynamoDbTable<TourDailyReportData> tourDailyReportTable;

    @Mock
    private DynamoDbTable<TravelAgentDailyReportData> travelAgencyDailyReport;

    @Mock
    private DynamoDbTable<TourWeeklyReportData> tourWeeklyReportDynamoDbTable;

    @Mock
    private DynamoDbTable<TravelAgentWeeklyReportData> travelAgentWeeklyReportDynamoDbTable;

    @InjectMocks
    private ReportRepositoryImpl reportRepository;

    @Test
    void test_getTourDailyReportList_returnsItemsFromIndexQuery_whenDataExists() {
        reportRepository = newRepository();
        LocalDate start = LocalDate.of(2026, 7, 1);
        LocalDate end = LocalDate.of(2026, 7, 4);

        TourDailyReportData item = new TourDailyReportData();
        item.setTourId("tour-1");

        DynamoDbIndex<TourDailyReportData> index = mock(DynamoDbIndex.class);
        SdkIterable<Page<TourDailyReportData>> iterable =
                () -> List.of(Page.create(List.of(item))).iterator();

        when(tourDailyReportTable.index("tour-report-index")).thenReturn(index);
        when(index.query(any(Consumer.class))).thenReturn(iterable);

        List<TourDailyReportData> result = reportRepository.getTourDailyReportList(start, end);

        assertEquals(1, result.size());
        assertEquals("tour-1", result.get(0).getTourId());
    }

    @Test
    void test_getTravelAgentDailyReportList_returnsItemsFromIndexQuery_whenDataExists() {
        reportRepository = newRepository();
        LocalDate start = LocalDate.of(2026, 7, 1);
        LocalDate end = LocalDate.of(2026, 7, 4);

        TravelAgentDailyReportData item = new TravelAgentDailyReportData();
        item.setTravelAgentEmail("agent@example.com");

        DynamoDbIndex<TravelAgentDailyReportData> index = mock(DynamoDbIndex.class);
        SdkIterable<Page<TravelAgentDailyReportData>> iterable =
                () -> List.of(Page.create(List.of(item))).iterator();

        when(travelAgencyDailyReport.index("tour-report-index")).thenReturn(index);
        when(index.query(any(Consumer.class))).thenReturn(iterable);

        List<TravelAgentDailyReportData> result = reportRepository.getTravelAgentDailyReportList(start, end);

        assertEquals(1, result.size());
        assertEquals("agent@example.com", result.get(0).getTravelAgentEmail());
    }

    @Test
    void test_getTourWeeklyReports_returnsItems_whenQueryFindsData() {
        reportRepository = newRepository();
        LocalDate reportDate = LocalDate.of(2026, 7, 4);

        TourWeeklyReportData item = new TourWeeklyReportData();
        PageIterable<TourWeeklyReportData> iterable =
                PageIterable.create(() -> List.of(Page.create(List.of(item))).iterator());

        DynamoDbIndex<TourWeeklyReportData> index = mock(DynamoDbIndex.class);
        when(tourWeeklyReportDynamoDbTable.index("tour-report-index")).thenReturn(index);
        when(index.query(any(Consumer.class))).thenReturn(iterable);

        List<TourWeeklyReportData> result = reportRepository.getTourWeeklyReports(reportDate);

        assertEquals(1, result.size());
    }

    @Test
    void test_getTravelAgentWeeklyReports_returnsItems_whenQueryFindsData() {
        reportRepository = newRepository();
        LocalDate reportDate = LocalDate.of(2026, 7, 4);

        TravelAgentWeeklyReportData item = new TravelAgentWeeklyReportData();
        PageIterable<TravelAgentWeeklyReportData> iterable =
                PageIterable.create(() -> List.of(Page.create(List.of(item))).iterator());

        DynamoDbIndex<TravelAgentWeeklyReportData> index = mock(DynamoDbIndex.class);
        when(travelAgentWeeklyReportDynamoDbTable.index("tour-report-index")).thenReturn(index);
        when(index.query(any(Consumer.class))).thenReturn(iterable);

        List<TravelAgentWeeklyReportData> result = reportRepository.getTravelAgentWeeklyReports(reportDate);

        assertEquals(1, result.size());
    }

    @Test
    void test_saveWeeklyTourReports_writesInBatches_whenListIsLargerThanLimit() {
        reportRepository = newRepository();
        List<TourWeeklyReportData> reports = new ArrayList<>();
        for (int i = 0; i < 26; i++) {
            reports.add(new TourWeeklyReportData());
        }
        when(tourWeeklyReportDynamoDbTable.tableSchema()).thenReturn(TableSchema.fromBean(TourWeeklyReportData.class));
        when(tourWeeklyReportDynamoDbTable.tableName()).thenReturn("tour-weekly");

        reportRepository.saveWeeklyTourReports(reports);

        verify(dynamoDbEnhancedClient, times(2)).batchWriteItem(any(BatchWriteItemEnhancedRequest.class));
    }

    @Test
    void test_saveWeeklyTaReports_writesInBatches_whenListIsLargerThanLimit() {
        reportRepository = newRepository();
        List<TravelAgentWeeklyReportData> reports = new ArrayList<>();
        for (int i = 0; i < 26; i++) {
            reports.add(new TravelAgentWeeklyReportData());
        }
        when(travelAgentWeeklyReportDynamoDbTable.tableSchema()).thenReturn(TableSchema.fromBean(TravelAgentWeeklyReportData.class));
        when(travelAgentWeeklyReportDynamoDbTable.tableName()).thenReturn("agent-weekly");

        reportRepository.saveWeeklyTaReports(reports);

        verify(dynamoDbEnhancedClient, times(2)).batchWriteItem(any(BatchWriteItemEnhancedRequest.class));
    }

    @Test
    void test_updateTourReportByState_buildsConfirmedExpression_whenStateIsConfirmed() {
        reportRepository = newRepository();
        reportRepository.updateTourReportByState(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                BookingStatus.CONFIRMED,
                BigDecimal.valueOf(10),
                BigDecimal.ZERO,
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<UpdateItemRequest> captor = ArgumentCaptor.forClass(UpdateItemRequest.class);
        verify(dynamoDbClient).updateItem(captor.capture());

        UpdateItemRequest request = captor.getValue();
        assertEquals("confirmedToursCount", request.expressionAttributeNames().get("#a1"));
        assertEquals("confirmedToursRevenue", request.expressionAttributeNames().get("#a2"));
        assertTrue(request.updateExpression().contains("#a3 = if_not_exists(#a3, :zero) + :los"));
    }

    @Test
    void test_updateTourReportByState_buildsCancelledExpression_whenStateIsCanceled() {
        reportRepository = newRepository();
        reportRepository.updateTourReportByState(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                BookingStatus.CANCELED,
                BigDecimal.valueOf(10),
                BigDecimal.valueOf(3),
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<UpdateItemRequest> captor = ArgumentCaptor.forClass(UpdateItemRequest.class);
        verify(dynamoDbClient).updateItem(captor.capture());

        UpdateItemRequest request = captor.getValue();
        assertEquals("cancelledToursCount", request.expressionAttributeNames().get("#a1"));
        assertEquals("cancelledToursRevenue", request.expressionAttributeNames().get("#a2"));
        assertEquals("3", request.expressionAttributeValues().get(":los").n());
    }

    @Test
    void test_updateTourReportByState_throwsException_whenStateIsUnsupported() {
        reportRepository = newRepository();
        IllegalArgumentException ex = assertThrows(
                IllegalArgumentException.class,
                () -> reportRepository.updateTourReportByState(
                        LocalDate.of(2026, 7, 4),
                        "pk-1",
                        "sk-1",
                        BookingStatus.STARTED,
                        BigDecimal.ONE,
                        BigDecimal.ONE,
                        "tour-1",
                        "Paris, France",
                        "Tour Name"
                )
        );

        assertTrue(ex.getMessage().contains("Unknown state"));
    }

    @Test
    void test_updateTravelAgentReportByState_buildsFinishedExpression_whenStateIsFinished() {
        reportRepository = newRepository();
        reportRepository.updateTravelAgentReportByState(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                BookingStatus.FINISHED,
                BigDecimal.valueOf(8),
                BigDecimal.ZERO,
                "Agent Name",
                "agent@example.com"
        );

        ArgumentCaptor<UpdateItemRequest> captor = ArgumentCaptor.forClass(UpdateItemRequest.class);
        verify(dynamoDbClient).updateItem(captor.capture());

        UpdateItemRequest request = captor.getValue();
        assertEquals("finishedToursCount", request.expressionAttributeNames().get("#a1"));
        assertEquals("finishedToursRevenue", request.expressionAttributeNames().get("#a2"));
    }

    @Test
    void test_updateTravelAgentReportByState_throwsException_whenStateIsUnsupported() {
        reportRepository = newRepository();
        IllegalArgumentException ex = assertThrows(
                IllegalArgumentException.class,
                () -> reportRepository.updateTravelAgentReportByState(
                        LocalDate.of(2026, 7, 4),
                        "pk-1",
                        "sk-1",
                        BookingStatus.BOOKED,
                        BigDecimal.ONE,
                        BigDecimal.ONE,
                        "Agent Name",
                        "agent@example.com"
                )
        );

        assertTrue(ex.getMessage().contains("Unknown state"));
    }

    @Test
    void test_updateTourReportReview_includesFeedbackCount_whenIsNewIsTrue() {
        reportRepository = newRepository();
        when(reportsTable.tableName()).thenReturn("reports-table");

        reportRepository.updateTourReportReview(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                2,
                4,
                true,
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<UpdateItemRequest> captor = ArgumentCaptor.forClass(UpdateItemRequest.class);
        verify(dynamoDbClient, times(2)).updateItem(captor.capture());

        UpdateItemRequest firstUpdate = captor.getAllValues().get(0);
        assertTrue(firstUpdate.updateExpression().contains("#a1 = if_not_exists(#a1, :zero) + :inc"));
        assertEquals("feedbackCount", firstUpdate.expressionAttributeNames().get("#a1"));
    }

    @Test
    void test_updateTourReportReview_excludesFeedbackCount_whenIsNewIsFalse() {
        reportRepository = newRepository();
        reportRepository.updateTourReportReview(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                -1,
                2,
                false,
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<UpdateItemRequest> captor = ArgumentCaptor.forClass(UpdateItemRequest.class);
        verify(dynamoDbClient, times(2)).updateItem(captor.capture());

        UpdateItemRequest firstUpdate = captor.getAllValues().get(0);
        assertFalse(firstUpdate.updateExpression().contains("#a1 = if_not_exists(#a1, :zero) + :inc"));
        assertEquals("feedbackRatingSum", firstUpdate.expressionAttributeNames().get("#a2"));
    }

    @Test
    void test_updateTravelAgentReportReview_handlesConditionalFailure_whenMinRateAlreadyLower() {
        reportRepository = newRepository();
        when(dynamoDbClient.updateItem(any(UpdateItemRequest.class)))
                .thenReturn(null)
                .thenThrow(ConditionalCheckFailedException.builder().build());

        assertDoesNotThrow(() -> reportRepository.updateTravelAgentReportReview(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                1,
                3,
                true,
                "Agent Name",
                "agent@example.com"
        ));

        verify(dynamoDbClient, times(2)).updateItem(any(UpdateItemRequest.class));
    }

    private ReportRepositoryImpl newRepository() {
        return new ReportRepositoryImpl(
                dynamoDbClient,
                dynamoDbEnhancedClient,
                reportsTable,
                tourDailyReportTable,
                travelAgencyDailyReport,
                tourWeeklyReportDynamoDbTable,
                travelAgentWeeklyReportDynamoDbTable
        );
    }
}

package com.epam.edp.demo.repository;

import com.epam.edp.demo.entity.BookingStatus;
import com.epam.edp.demo.entity.TourDailyReportData;
import com.epam.edp.demo.entity.TourWeeklyReportData;
import com.epam.edp.demo.entity.TravelAgentDailyReportData;
import com.epam.edp.demo.entity.TravelAgentWeeklyReportData;
import org.bson.Document;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.mongodb.core.BulkOperations;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Query;
import org.springframework.data.mongodb.core.query.Update;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.regex.Pattern;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertIterableEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class ReportRepositoryImplTest {

    @Mock
    private MongoTemplate mongoTemplate;

    @Mock
    private BulkOperations tourBulkOperations;

    @Mock
    private BulkOperations travelAgentBulkOperations;

    private ReportRepositoryImpl reportRepository;

    @BeforeEach
    void setUp() {
        reportRepository = new ReportRepositoryImpl(mongoTemplate);
    }

    @Test
    void getTourDailyReportList_queriesMongoByDailyTourAndDateRange() {
        TourDailyReportData item = new TourDailyReportData();
        item.setTourId("tour-1");
        when(mongoTemplate.find(any(Query.class), eq(TourDailyReportData.class), eq("reports")))
                .thenReturn(List.of(item));

        LocalDate start = LocalDate.of(2026, 7, 1);
        LocalDate end = LocalDate.of(2026, 7, 4);

        List<TourDailyReportData> result = reportRepository.getTourDailyReportList(start, end);

        assertIterableEquals(List.of(item), result);

        ArgumentCaptor<Query> captor = ArgumentCaptor.forClass(Query.class);
        verify(mongoTemplate).find(captor.capture(), eq(TourDailyReportData.class), eq("reports"));
        Document query = captor.getValue().getQueryObject();
        assertEquals("DAILY#TOUR", query.get("tourDaily"));
        Document range = (Document) query.get("tourReportSk");
        assertEquals(start.toString(), range.get("$gte"));
        assertEquals(end + "#\uffff", range.get("$lte"));
    }

    @Test
    void getTravelAgentDailyReportList_queriesMongoByDailyAgentAndDateRange() {
        TravelAgentDailyReportData item = new TravelAgentDailyReportData();
        item.setTravelAgentEmail("agent@example.com");
        when(mongoTemplate.find(any(Query.class), eq(TravelAgentDailyReportData.class), eq("reports")))
                .thenReturn(List.of(item));

        LocalDate start = LocalDate.of(2026, 7, 1);
        LocalDate end = LocalDate.of(2026, 7, 4);

        List<TravelAgentDailyReportData> result = reportRepository.getTravelAgentDailyReportList(start, end);

        assertIterableEquals(List.of(item), result);

        ArgumentCaptor<Query> captor = ArgumentCaptor.forClass(Query.class);
        verify(mongoTemplate).find(captor.capture(), eq(TravelAgentDailyReportData.class), eq("reports"));
        Document query = captor.getValue().getQueryObject();
        assertEquals("DAILY#AGENT", query.get("tourDaily"));
        Document range = (Document) query.get("tourReportSk");
        assertEquals(start.toString(), range.get("$gte"));
        assertEquals(end + "#\uffff", range.get("$lte"));
    }

    @Test
    void getTourWeeklyReports_queriesMongoByWeeklyTourRegex() {
        TourWeeklyReportData item = new TourWeeklyReportData();
        when(mongoTemplate.find(any(Query.class), eq(TourWeeklyReportData.class), eq("reports")))
                .thenReturn(List.of(item));

        LocalDate reportDate = LocalDate.of(2026, 7, 4);

        List<TourWeeklyReportData> result = reportRepository.getTourWeeklyReports(reportDate);

        assertIterableEquals(List.of(item), result);

        ArgumentCaptor<Query> captor = ArgumentCaptor.forClass(Query.class);
        verify(mongoTemplate).find(captor.capture(), eq(TourWeeklyReportData.class), eq("reports"));
        Document query = captor.getValue().getQueryObject();
        assertEquals("WEEKLY#TOUR", query.get("tourDaily"));
        Pattern regex = (Pattern) query.get("tourReportSk");
        assertEquals("^" + reportDate, regex.pattern());
    }

    @Test
    void getTravelAgentWeeklyReports_queriesMongoByWeeklyAgentRegex() {
        TravelAgentWeeklyReportData item = new TravelAgentWeeklyReportData();
        when(mongoTemplate.find(any(Query.class), eq(TravelAgentWeeklyReportData.class), eq("reports")))
                .thenReturn(List.of(item));

        LocalDate reportDate = LocalDate.of(2026, 7, 4);

        List<TravelAgentWeeklyReportData> result = reportRepository.getTravelAgentWeeklyReports(reportDate);

        assertIterableEquals(List.of(item), result);

        ArgumentCaptor<Query> captor = ArgumentCaptor.forClass(Query.class);
        verify(mongoTemplate).find(captor.capture(), eq(TravelAgentWeeklyReportData.class), eq("reports"));
        Document query = captor.getValue().getQueryObject();
        assertEquals("WEEKLY#AGENT", query.get("tourDaily"));
        Pattern regex = (Pattern) query.get("tourReportSk");
        assertEquals("^" + reportDate, regex.pattern());
    }

    @Test
    void saveWeeklyTourReports_usesMongoBulkInsertAndExecute() {
        List<TourWeeklyReportData> reports = List.of(new TourWeeklyReportData(), new TourWeeklyReportData());
        when(mongoTemplate.bulkOps(BulkOperations.BulkMode.UNORDERED, TourWeeklyReportData.class, "reports"))
                .thenReturn(tourBulkOperations);

        reportRepository.saveWeeklyTourReports(reports);

        verify(tourBulkOperations, times(2)).insert(any(TourWeeklyReportData.class));
        verify(tourBulkOperations).execute();
    }

    @Test
    void saveWeeklyTaReports_usesMongoBulkInsertAndExecute() {
        List<TravelAgentWeeklyReportData> reports = List.of(new TravelAgentWeeklyReportData(), new TravelAgentWeeklyReportData());
        when(mongoTemplate.bulkOps(BulkOperations.BulkMode.UNORDERED, TravelAgentWeeklyReportData.class, "reports"))
                .thenReturn(travelAgentBulkOperations);

        reportRepository.saveWeeklyTaReports(reports);

        verify(travelAgentBulkOperations, times(2)).insert(any(TravelAgentWeeklyReportData.class));
        verify(travelAgentBulkOperations).execute();
    }

    @Test
    void updateTourReportByState_upsertsConfirmedCountersAndInsertFields() {
        reportRepository.updateTourReportByState(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                BookingStatus.CONFIRMED,
                BigDecimal.TEN,
                BigDecimal.ZERO,
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<Query> queryCaptor = ArgumentCaptor.forClass(Query.class);
        ArgumentCaptor<Update> updateCaptor = ArgumentCaptor.forClass(Update.class);
        verify(mongoTemplate).upsert(queryCaptor.capture(), updateCaptor.capture(), eq(TourDailyReportData.class), eq("reports"));

        assertPkAndSk(queryCaptor.getValue(), "pk-1", "sk-1");
        Document setOnInsert = (Document) updateCaptor.getValue().getUpdateObject().get("$setOnInsert");
        assertEquals("tour-1", setOnInsert.get("tourId"));
        assertEquals("Tour Name", setOnInsert.get("tourName"));
        assertEquals("Paris, France", setOnInsert.get("destination"));
        assertEquals("DAILY#TOUR", setOnInsert.get("tourDaily"));
        assertEquals("2026-07-04#tour-1", setOnInsert.get("tourReportSk"));

        Document inc = (Document) updateCaptor.getValue().getUpdateObject().get("$inc");
        assertEquals(1, inc.get("confirmedToursCount"));
        assertEquals(BigDecimal.TEN, inc.get("confirmedToursRevenue"));
    }

    @Test
    void updateTourReportByState_upsertsCancelledCountersAndLoss() {
        reportRepository.updateTourReportByState(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                BookingStatus.CANCELED,
                BigDecimal.TEN,
                BigDecimal.valueOf(3),
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<Update> updateCaptor = ArgumentCaptor.forClass(Update.class);
        verify(mongoTemplate).upsert(any(Query.class), updateCaptor.capture(), eq(TourDailyReportData.class), eq("reports"));

        Document inc = (Document) updateCaptor.getValue().getUpdateObject().get("$inc");
        assertEquals(1, inc.get("cancelledToursCount"));
        assertEquals(BigDecimal.TEN, inc.get("cancelledToursRevenue"));
        assertEquals(BigDecimal.valueOf(3), inc.get("cancelledToursLoss"));
    }

    @Test
    void updateTourReportByState_throwsException_whenStateIsUnsupported() {
        IllegalArgumentException ex = assertThrows(
                IllegalArgumentException.class,
                () -> reportRepository.updateTourReportByState(
                        LocalDate.of(2026, 7, 4),
                        "pk-1",
                        "sk-1",
                        BookingStatus.STARTED,
                        BigDecimal.ONE,
                        BigDecimal.ONE,
                        "tour-1",
                        "Paris, France",
                        "Tour Name"
                )
        );

        assertTrue(ex.getMessage().contains("Unknown state"));
    }

    @Test
    void updateTravelAgentReportByState_upsertsFinishedCountersAndInsertFields() {
        reportRepository.updateTravelAgentReportByState(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                BookingStatus.FINISHED,
                BigDecimal.valueOf(8),
                BigDecimal.ZERO,
                "Agent Name",
                "agent@example.com"
        );

        ArgumentCaptor<Query> queryCaptor = ArgumentCaptor.forClass(Query.class);
        ArgumentCaptor<Update> updateCaptor = ArgumentCaptor.forClass(Update.class);
        verify(mongoTemplate).upsert(queryCaptor.capture(), updateCaptor.capture(), eq(TravelAgentDailyReportData.class), eq("reports"));

        assertPkAndSk(queryCaptor.getValue(), "pk-1", "sk-1");
        Document setOnInsert = (Document) updateCaptor.getValue().getUpdateObject().get("$setOnInsert");
        assertEquals("Agent Name", setOnInsert.get("travelAgentName"));
        assertEquals("agent@example.com", setOnInsert.get("travelAgentEmail"));
        assertEquals("DAILY#AGENT", setOnInsert.get("tourDaily"));
        assertEquals("2026-07-04#agent@example.com", setOnInsert.get("tourReportSk"));

        Document inc = (Document) updateCaptor.getValue().getUpdateObject().get("$inc");
        assertEquals(1, inc.get("finishedToursCount"));
        assertEquals(BigDecimal.valueOf(8), inc.get("finishedToursRevenue"));
    }

    @Test
    void updateTravelAgentReportByState_throwsException_whenStateIsUnsupported() {
        IllegalArgumentException ex = assertThrows(
                IllegalArgumentException.class,
                () -> reportRepository.updateTravelAgentReportByState(
                        LocalDate.of(2026, 7, 4),
                        "pk-1",
                        "sk-1",
                        BookingStatus.BOOKED,
                        BigDecimal.ONE,
                        BigDecimal.ONE,
                        "Agent Name",
                        "agent@example.com"
                )
        );

        assertTrue(ex.getMessage().contains("Unknown state"));
    }

    @Test
    void updateTourReportReview_includesFeedbackCount_whenReviewIsNew() {
        reportRepository.updateTourReportReview(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                2,
                4,
                true,
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<Update> updateCaptor = ArgumentCaptor.forClass(Update.class);
        verify(mongoTemplate).upsert(any(Query.class), updateCaptor.capture(), eq(TourDailyReportData.class), eq("reports"));

        Document update = updateCaptor.getValue().getUpdateObject();
        Document inc = (Document) update.get("$inc");
        assertEquals(1, inc.get("feedbackCount"));
        assertEquals(2, inc.get("feedbackRatingSum"));
        Document min = (Document) update.get("$min");
        assertEquals(4, min.get("minFeedbackRate"));
    }

    @Test
    void updateTourReportReview_excludesFeedbackCount_whenReviewIsNotNew() {
        reportRepository.updateTourReportReview(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                -1,
                2,
                false,
                "tour-1",
                "Paris, France",
                "Tour Name"
        );

        ArgumentCaptor<Update> updateCaptor = ArgumentCaptor.forClass(Update.class);
        verify(mongoTemplate).upsert(any(Query.class), updateCaptor.capture(), eq(TourDailyReportData.class), eq("reports"));

        Document update = updateCaptor.getValue().getUpdateObject();
        Document inc = (Document) update.get("$inc");
        assertEquals(-1, inc.get("feedbackRatingSum"));
        assertTrue(!inc.containsKey("feedbackCount"));
    }

    @Test
    void updateTravelAgentReportReview_upsertsAgentFieldsAndReviewAggregates() {
        reportRepository.updateTravelAgentReportReview(
                LocalDate.of(2026, 7, 4),
                "pk-1",
                "sk-1",
                1,
                3,
                true,
                "Agent Name",
                "agent@example.com"
        );

        ArgumentCaptor<Query> queryCaptor = ArgumentCaptor.forClass(Query.class);
        ArgumentCaptor<Update> updateCaptor = ArgumentCaptor.forClass(Update.class);
        verify(mongoTemplate).upsert(queryCaptor.capture(), updateCaptor.capture(), eq(TravelAgentDailyReportData.class), eq("reports"));

        assertPkAndSk(queryCaptor.getValue(), "pk-1", "sk-1");
        Document setOnInsert = (Document) updateCaptor.getValue().getUpdateObject().get("$setOnInsert");
        assertEquals("Agent Name", setOnInsert.get("travelAgentName"));
        assertEquals("agent@example.com", setOnInsert.get("travelAgentEmail"));
        assertEquals("DAILY#AGENT", setOnInsert.get("tourDaily"));
        assertEquals("2026-07-04#agent@example.com", setOnInsert.get("tourReportSk"));

        Document inc = (Document) updateCaptor.getValue().getUpdateObject().get("$inc");
        assertEquals(1, inc.get("feedbackCount"));
        assertEquals(1, inc.get("feedbackRatingSum"));
        Document min = (Document) updateCaptor.getValue().getUpdateObject().get("$min");
        assertEquals(3, min.get("minFeedbackRate"));
    }

    private static void assertPkAndSk(Query query, String expectedPk, String expectedSk) {
        Document document = query.getQueryObject();
        assertEquals(expectedPk, document.get("pk"));
        assertEquals(expectedSk, document.get("sk"));
    }
}

package com.epam.edp.demo.repository;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import software.amazon.awssdk.services.dynamodb.DynamoDbClient;
import software.amazon.awssdk.services.dynamodb.model.AttributeValue;
import software.amazon.awssdk.services.dynamodb.model.ScanRequest;
import software.amazon.awssdk.services.dynamodb.model.ScanResponse;

import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentCaptor.forClass;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import org.mockito.ArgumentCaptor;

@ExtendWith(MockitoExtension.class)
class TravelAgentListRepositoryTest {

    private static final String TABLE_NAME = "travel-agents-table";

    @Mock
    private DynamoDbClient dynamoDbClient;

    private TravelAgentListRepository travelAgentListRepository;

    @BeforeEach
    void setUp() {
        travelAgentListRepository = new TravelAgentListRepository(dynamoDbClient, TABLE_NAME);
    }

    @Test
    void getAllTravelAgentEmails_returnsEmails_whenTableHasItems() {
        ScanResponse response = ScanResponse.builder()
                .items(
                        Map.of("email", AttributeValue.builder().s("agent1@example.com").build()),
                        Map.of("email", AttributeValue.builder().s("agent2@example.com").build())
                )
                .build();

        when(dynamoDbClient.scan(any(ScanRequest.class))).thenReturn(response);

        List<String> emails = travelAgentListRepository.getAllTravelAgentEmails();

        assertNotNull(emails);
        assertEquals(2, emails.size());
        assertTrue(emails.contains("agent1@example.com"));
        assertTrue(emails.contains("agent2@example.com"));
    }

    @Test
    void getAllTravelAgentEmails_returnsEmptyList_whenTableIsEmpty() {
        ScanResponse response = ScanResponse.builder().build();

        when(dynamoDbClient.scan(any(ScanRequest.class))).thenReturn(response);

        List<String> emails = travelAgentListRepository.getAllTravelAgentEmails();

        assertNotNull(emails);
        assertTrue(emails.isEmpty());
    }

    @Test
    void getAllTravelAgentEmails_scanRequestUsesCorrectTableName() {
        ScanResponse response = ScanResponse.builder().build();
        when(dynamoDbClient.scan(any(ScanRequest.class))).thenReturn(response);

        travelAgentListRepository.getAllTravelAgentEmails();

        ArgumentCaptor<ScanRequest> captor = forClass(ScanRequest.class);
        verify(dynamoDbClient).scan(captor.capture());

        ScanRequest capturedRequest = captor.getValue();
        assertEquals(TABLE_NAME, capturedRequest.tableName());
    }

    @Test
    void getAllTravelAgentEmails_scanRequestProjectsEmailField() {
        ScanResponse response = ScanResponse.builder().build();
        when(dynamoDbClient.scan(any(ScanRequest.class))).thenReturn(response);

        travelAgentListRepository.getAllTravelAgentEmails();

        ArgumentCaptor<ScanRequest> captor = forClass(ScanRequest.class);
        verify(dynamoDbClient).scan(captor.capture());

        ScanRequest capturedRequest = captor.getValue();
        assertEquals("email", capturedRequest.projectionExpression());
    }

    @Test
    void getAllTravelAgentEmails_returnsSingleEmail_whenTableHasOneItem() {
        ScanResponse response = ScanResponse.builder()
                .items(Map.of("email", AttributeValue.builder().s("solo@example.com").build()))
                .build();

        when(dynamoDbClient.scan(any(ScanRequest.class))).thenReturn(response);

        List<String> emails = travelAgentListRepository.getAllTravelAgentEmails();

        assertNotNull(emails);
        assertEquals(1, emails.size());
        assertEquals("solo@example.com", emails.get(0));
    }
}

package com.epam.edp.demo.repository;

import com.epam.edp.demo.entity.travelagent.TravelAgent;
import org.bson.Document;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.ArgumentCaptor;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.mongodb.core.MongoTemplate;
import org.springframework.data.mongodb.core.query.Query;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertIterableEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class TravelAgentListRepositoryTest {

    @Mock
    private MongoTemplate mongoTemplate;

    private TravelAgentListRepository travelAgentListRepository;

    @BeforeEach
    void setUp() {
        travelAgentListRepository = new TravelAgentListRepository(mongoTemplate);
    }

    @Test
    void getAllTravelAgentEmails_returnsEmails_whenCollectionHasItems() {
        when(mongoTemplate.find(any(Query.class), eq(TravelAgent.class), eq("travel_agents")))
                .thenReturn(List.of(
                        travelAgent("agent1@example.com"),
                        travelAgent("agent2@example.com")
                ));

        List<String> emails = travelAgentListRepository.getAllTravelAgentEmails();

        assertIterableEquals(List.of("agent1@example.com", "agent2@example.com"), emails);
    }

    @Test
    void getAllTravelAgentEmails_returnsEmptyList_whenCollectionIsEmpty() {
        when(mongoTemplate.find(any(Query.class), eq(TravelAgent.class), eq("travel_agents")))
                .thenReturn(List.of());

        List<String> emails = travelAgentListRepository.getAllTravelAgentEmails();

        assertTrue(emails.isEmpty());
    }

    @Test
    void getAllTravelAgentEmails_queriesTravelAgentsCollection_andProjectsOnlyEmail() {
        when(mongoTemplate.find(any(Query.class), eq(TravelAgent.class), eq("travel_agents")))
                .thenReturn(List.of());

        travelAgentListRepository.getAllTravelAgentEmails();

        ArgumentCaptor<Query> captor = ArgumentCaptor.forClass(Query.class);
        verify(mongoTemplate).find(captor.capture(), eq(TravelAgent.class), eq("travel_agents"));

        Query query = captor.getValue();
        Document fields = query.getFieldsObject();
        assertEquals(1, fields.get("email"));
        assertTrue(query.getQueryObject().isEmpty());
    }

    private static TravelAgent travelAgent(String email) {
        return new TravelAgent("Agent", email, "555", "tg");
    }
}
